<script setup>
import AppShell from '@/Components/AppShell.vue';
import DataTableFooter from '@/Components/DataTableFooter.vue';
import Modal from '@/Components/Modal.vue';
import SortButton from '@/Components/SortButton.vue';
import { router, useForm } from '@inertiajs/vue3';
import { reactive, ref } from 'vue';

const props = defineProps({ vendors:Object, stats:Object, filters:Object });
const filter = reactive({ search:'', category:'', status:'', sort:'name', direction:'asc', per_page:25, ...props.filters });
const modal = ref(false), editing = ref(null);
const form = useForm({ name:'', abbreviation:'', category:'REGULAR', remarks:'', is_active:true });
const load = () => router.get('/coordinator/vendors', filter, { preserveState:true, preserveScroll:true, replace:true });
const reset = () => router.get('/coordinator/vendors', {}, { preserveScroll:true, replace:true });
const sort = column => { filter.direction=filter.sort===column&&filter.direction==='asc'?'desc':'asc'; filter.sort=column; load(); };
const create = () => { editing.value=null; form.reset(); form.clearErrors(); Object.assign(form,{category:'REGULAR',remarks:'',is_active:true}); modal.value=true; };
const edit = vendor => { editing.value=vendor; form.clearErrors(); Object.assign(form,{name:vendor.name,abbreviation:vendor.abbreviation,category:vendor.category,remarks:vendor.remarks||'',is_active:Boolean(vendor.is_active)}); modal.value=true; };
const save = () => { const options={preserveScroll:true,onSuccess:()=>{modal.value=false;form.reset();}}; editing.value ? form.patch(`/coordinator/vendors/${editing.value.id}`,options) : form.post('/coordinator/vendors',options); };
</script>

<template><AppShell title="Manajemen Vendor" subtitle="Master perusahaan vendor dan klasifikasi layanan" eyebrow="Koordinator Sarana · Master Data">
<template #hero-title>Manajemen Vendor</template><template #hero-copy>Kelola identitas perusahaan, singkatan, kategori reguler, dan jadwal pelaporan.</template>
<section class="mb-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><article class="metric-card"><p>Total Vendor</p><strong>{{stats.total}}</strong><span>Master perusahaan</span></article><article class="metric-card"><p>Reguler</p><strong>{{stats.regular}}</strong><span>Daily dan weekly</span></article><article class="metric-card"><p>Non Reguler</p><strong>{{stats.nonRegular}}</strong><span>Sesuai kebutuhan</span></article><article class="metric-card"><p>Vendor Aktif</p><strong>{{stats.active}}</strong><span>Dapat digunakan sistem</span></article></section>
<form class="panel mb-5" @submit.prevent="load"><div class="grid gap-3 md:grid-cols-2 xl:grid-cols-[1fr_220px_180px_auto_auto_auto]"><input v-model="filter.search" class="control" placeholder="Cari nama atau singkatan..."><select v-model="filter.category" class="control"><option value="">Semua kategori</option><option value="REGULAR">Reguler</option><option value="NON_REGULAR">Non Reguler</option></select><select v-model="filter.status" class="control"><option value="">Semua status</option><option value="active">Aktif</option><option value="inactive">Nonaktif</option></select><button class="btn">Terapkan</button><button type="button" class="btn-ghost" @click="reset">Reset</button><button type="button" class="btn-ghost" @click="create">+ Tambah Vendor</button></div></form>
<section class="panel overflow-hidden p-0"><div class="flex items-center justify-between border-b px-5 py-4"><div><h2 class="panel-title">Daftar Master Vendor</h2><p class="panel-copy">DataTable server-side · singkatan dan nama harus unik</p></div><span class="text-xs text-slate-400">{{vendors.total}} vendor</span></div><div class="overflow-x-auto"><table class="data-table min-w-[850px]"><thead><tr><th>No</th><th><SortButton label="Nama Panjang" column="name" :sort="filter.sort" :direction="filter.direction" @sort="sort"/></th><th><SortButton label="Singkatan" column="abbreviation" :sort="filter.sort" :direction="filter.direction" @sort="sort"/></th><th><SortButton label="Kategori" column="category" :sort="filter.sort" :direction="filter.direction" @sort="sort"/></th><th>Remarks</th><th><SortButton label="Status" column="is_active" :sort="filter.sort" :direction="filter.direction" @sort="sort"/></th><th>Aksi</th></tr></thead><tbody><tr v-for="(vendor,index) in vendors.data" :key="vendor.id"><td>{{vendors.from+index}}</td><td><b>{{vendor.name}}</b></td><td><span class="rounded-lg bg-slate-100 px-2.5 py-1 font-black">{{vendor.abbreviation}}</span></td><td><span class="status-badge" :class="vendor.category==='REGULAR'?'status-approved':'bg-amber-50 text-amber-700'">{{vendor.category==='REGULAR'?'Reguler':'Non Reguler'}}</span></td><td>{{vendor.remarks||'—'}}</td><td><span class="status-badge" :class="vendor.is_active?'status-approved':'status-rejected'">{{vendor.is_active?'Aktif':'Nonaktif'}}</span></td><td><button class="font-black text-red-600" type="button" @click="edit(vendor)">Edit</button></td></tr><tr v-if="!vendors.data.length"><td colspan="7" class="py-14 text-center text-slate-500">Vendor tidak ditemukan.</td></tr></tbody></table></div><DataTableFooter :paginator="vendors" :per-page="filter.per_page" @update:per-page="value=>{filter.per_page=value;load()}"/></section>
<Modal :show="modal" max-width="2xl" @close="modal=false"><form @submit.prevent="save"><div class="border-b px-6 py-5"><p class="text-[10px] font-black uppercase tracking-[.2em] text-red-600">Master Vendor</p><h2 class="mt-1 text-2xl font-black">{{editing?'Edit Vendor':'Tambah Vendor'}}</h2></div><div class="grid gap-4 p-6 sm:grid-cols-2"><label class="text-xs font-bold sm:col-span-2">Nama panjang<input v-model="form.name" class="control mt-2" placeholder="Nama resmi perusahaan"><span class="err">{{form.errors.name}}</span></label><label class="text-xs font-bold">Singkatan<input v-model="form.abbreviation" class="control mt-2 uppercase" placeholder="Contoh: BAS"><span class="err">{{form.errors.abbreviation}}</span></label><label class="text-xs font-bold">Kategori<select v-model="form.category" class="control mt-2"><option value="REGULAR">Reguler</option><option value="NON_REGULAR">Non Reguler</option></select><span class="err">{{form.errors.category}}</span></label><label class="text-xs font-bold sm:col-span-2">Remarks<input v-model="form.remarks" class="control mt-2" placeholder="Daily, Weekly atau keterangan lain"><span class="err">{{form.errors.remarks}}</span></label><label class="flex items-center gap-3 rounded-xl border p-4 sm:col-span-2"><input v-model="form.is_active" type="checkbox" class="rounded text-red-600"><span><b class="block text-sm">Vendor aktif</b><small class="text-slate-500">Vendor tersedia untuk digunakan pada sistem.</small></span></label></div><div class="flex justify-end gap-3 border-t px-6 py-4"><button type="button" class="btn-ghost" @click="modal=false">Batal</button><button class="btn" :disabled="form.processing">{{form.processing?'Menyimpan...':'Simpan Vendor'}}</button></div></form></Modal>
</AppShell></template>
